"use client";

import Link from "next/link";
import dynamic from "next/dynamic";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ArrowDownLeft, ArrowLeftRight, ArrowUpRight, Bell, CalendarDays, Check, ChevronLeft, ChevronRight, CircleHelp, SlidersHorizontal, Download, Ellipsis, LayoutDashboard, LogOut, Menu, Moon, MoreHorizontal, Plus, Search, Settings2, ShieldCheck, Lightbulb, Sun, Target, Trash2, TrendingUp, Wallet, X, CreditCard, ChartNoAxesCombined, FileText, Layers3, Pencil, Play, Pause, Upload, CheckCircle2, AlertCircle, Info, PiggyBank } from "lucide-react";
import type { Currency, Locale, Snapshot, Transaction } from "@/lib/contracts";
import { getStoredLocale, hasStoredLocale, usePreferences } from "@/components/providers";
import { LanguageSelect } from "@/components/language-select";
import { createTranslator, isRtl, localeTag, type Translator } from "@/lib/i18n";
import { categoryLabel, dateLabel, major, minor, money, monthlyRows, sum, thisMonth, today } from "./finance/utils";
import "./finance.css";

const CashflowChart = dynamic(() => import("./finance/charts").then((m) => m.CashflowChart), { loading: () => <div className="chart-empty" aria-busy="true">…</div> });
const SpendingChart = dynamic(() => import("./finance/charts").then((m) => m.SpendingChart), { loading: () => <div className="chart-empty" aria-busy="true">…</div> });
const ScenarioSimulator = dynamic(() => import("./finance/scenario-simulator"));
const ImportPanel = dynamic(() => import("./finance/import-panel").then((m) => m.ImportPanel));

type T = Translator;
interface Field { key: string; ar: string; en: string; type?: "text" | "money" | "date" | "month" | "select" | "textarea" | "email"; options?: { value: string; label: string; kind?: string }[]; required?: boolean; }
interface DialogSpec { title: string; action: string; fields: Field[]; values?: Record<string, string>; extra?: Record<string, unknown>; description?: string; }
interface Ctx { data: Snapshot; locale: Locale; t: T; currency: Currency; setCurrency: (c: Currency) => void; mutate: (body: Record<string, unknown>) => Promise<void>; open: (d: DialogSpec) => void; busy: boolean; }
const currencyOptions = ["ILS", "USD", "EUR"].map((c) => ({ value: c, label: c }));
const nav = [
  ["dashboard", "نظرة عامة", "Overview", LayoutDashboard], ["transactions", "المعاملات", "Transactions", ArrowLeftRight], ["accounts", "الحسابات", "Accounts", Wallet], ["budgets", "الميزانيات", "Budgets", Layers3], ["goals", "أهداف الادخار", "Savings goals", Target], ["recurring", "الاشتراكات", "Recurring", CreditCard], ["reports", "التقارير", "Reports", ChartNoAxesCombined], ["simulator", "اختبر قرارك", "Test a decision", SlidersHorizontal], ["insights", "الملاحظات المالية", "Money insights", Lightbulb],
] as const;

function accountOptions(data: Snapshot, currency?: Currency) { return data.accounts.filter((a) => !currency || a.currency === currency).map((a) => ({ value: a.id, label: `${a.name} · ${a.currency}` })); }
function categoryOptions(data: Snapshot, locale: Locale, kind?: string) { return data.categories.filter((c) => !kind || c.kind === kind).map((c) => ({ value: c.id, label: categoryLabel(data, c.id, locale), kind: c.kind })); }
function transactionDialog(ctx: Ctx, row?: Transaction): DialogSpec {
  return { title: row ? ctx.t("تعديل المعاملة", "Edit transaction") : ctx.t("إضافة معاملة", "Add transaction"), action: row ? "transaction.update" : "transaction.create", extra: row ? { id: row.id } : {}, values: row ? { kind: row.kind, accountId: row.accountId, categoryId: row.categoryId, amount: major(row.amount, ctx.locale), date: row.date.slice(0, 10), note: row.note } : { kind: "expense", date: today(ctx?.data.profile.timezone) }, fields: [
    { key: "kind", ar: "نوع المعاملة", en: "Type", type: "select", options: [{ value: "expense", label: ctx.t("مصروف", "Expense") }, { value: "income", label: ctx.t("دخل", "Income") }] },
    { key: "accountId", ar: "الحساب", en: "Account", type: "select", options: accountOptions(ctx.data) },
    { key: "categoryId", ar: "التصنيف", en: "Category", type: "select", options: categoryOptions(ctx.data, ctx.locale) },
    { key: "amount", ar: "المبلغ", en: "Amount", type: "money" }, { key: "date", ar: "التاريخ", en: "Date", type: "date" }, { key: "note", ar: "الوصف أو الملاحظة", en: "Description or note", required: false },
  ] };
}
function budgetDialog(ctx: Ctx): DialogSpec { return { title: ctx.t("ميزانية شهرية جديدة", "New monthly budget"), action: "budget.save", description: ctx.t("حفظ ميزانية لنفس التصنيف والشهر والعملة يحدّث الحد الحالي.", "Saving the same category, month and currency updates its existing limit."), values: { month: thisMonth(ctx.data.profile.timezone), currency: ctx.currency }, fields: [{ key: "categoryId", ar: "التصنيف", en: "Category", type: "select", options: categoryOptions(ctx.data, ctx.locale, "expense") }, { key: "amount", ar: "الحد الشهري", en: "Monthly limit", type: "money" }, { key: "currency", ar: "العملة", en: "Currency", type: "select", options: currencyOptions }, { key: "month", ar: "الشهر", en: "Month", type: "month" }] }; }
function goalDialog(ctx: Ctx): DialogSpec { return { title: ctx.t("هدف ادخار جديد", "New savings goal"), action: "goal.create", values: { currency: ctx.currency }, fields: [{ key: "name", ar: "اسم الهدف", en: "Goal name" }, { key: "target", ar: "المبلغ المستهدف", en: "Target amount", type: "money" }, { key: "currency", ar: "العملة", en: "Currency", type: "select", options: currencyOptions }, { key: "deadline", ar: "التاريخ المستهدف", en: "Target date", type: "date" }] }; }
function contributionDialog(ctx: Ctx, id: string): DialogSpec { const goal = ctx.data.goals.find((g) => g.id === id)!; return { title: ctx.t("أضف إلى {name}", "Contribute to {name}", { name: goal.name }), action: "contribution.create", extra: { goalId: id }, description: ctx.t("هذا تخصيص من رصيدك الحالي للهدف، وليس مصروفًا. لا يتغير إجمالي أموالك.", "This allocates existing funds to your goal. It is not an expense and does not reduce total funds."), values: { date: today(ctx?.data.profile.timezone) }, fields: [{ key: "accountId", ar: "الحساب المصدر", en: "Source account", type: "select", options: accountOptions(ctx.data, goal.currency) }, { key: "amount", ar: "المبلغ", en: "Amount", type: "money" }, { key: "date", ar: "التاريخ", en: "Date", type: "date" }] }; }

async function loadWorkspace(signal?: AbortSignal): Promise<Snapshot | null> {
  const requestLocale = getStoredLocale();
  const response = await fetch("/api/finance", { cache: "no-store", signal, headers: { "x-mizan-locale": requestLocale } });
  if (response.status === 401) return null;
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || createTranslator(requestLocale)("تعذر تحميل بياناتك.", "Unable to load your data."));
  return body as Snapshot;
}

export default function FinanceApp({ section = "dashboard" }: { section?: string }) {
  const { locale, setLocale, theme, setTheme, t } = usePreferences();
  const router = useRouter();
  const [data, setData] = useState<Snapshot | null>(null);
  const [dataVersion, setDataVersion] = useState(0);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [busy, setBusy] = useState(false);
  const [currency, setCurrency] = useState<Currency>("ILS");
  const [dialog, setDialog] = useState<DialogSpec | null>(null);
  const [menu, setMenu] = useState(false);
  const sidebarRef = useRef<HTMLElement>(null);
  const acceptWorkspace = useCallback((workspace: Snapshot | null) => {
    if (!workspace) { router.replace("/login"); return; }
    if (!workspace.profile.onboarded) { router.replace("/onboarding"); return; }
    if (!hasStoredLocale()) setLocale(workspace.profile.locale);
    setData(workspace); setDataVersion((version) => version + 1); setCurrency(workspace.profile.currency); setError("");
  }, [router, setLocale]);
  const refresh = useCallback(() => loadWorkspace().then(acceptWorkspace).catch((err: unknown) => {
    setError(err instanceof Error ? err.message : String(err));
  }), [acceptWorkspace]);
  useEffect(() => {
    const controller = new AbortController();
    void loadWorkspace(controller.signal).then((workspace) => {
      if (!controller.signal.aborted) acceptWorkspace(workspace);
    }).catch((err: unknown) => {
      if (!controller.signal.aborted) setError(err instanceof Error ? err.message : String(err));
    });
    return () => controller.abort();
  }, [acceptWorkspace]);
  useEffect(() => { if (notice) { const timer = setTimeout(() => setNotice(""), 5000); return () => clearTimeout(timer); } }, [notice]);
  useEffect(() => {
    if (!menu) return;
    const previous = document.activeElement as HTMLElement | null;
    const sidebar = sidebarRef.current;
    sidebar?.querySelector<HTMLElement>("button, a[href]")?.focus();
    function onKey(event: KeyboardEvent) {
      if (event.key === "Escape") { setMenu(false); return; }
      if (event.key !== "Tab" || !sidebar) return;
      const elements = [...sidebar.querySelectorAll<HTMLElement>("a[href], button:not(:disabled)")].filter((element) => element.getClientRects().length > 0);
      const first = elements[0], last = elements.at(-1);
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    }
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("keydown", onKey); if (previous?.isConnected) previous.focus(); };
  }, [menu]);
  async function mutate(body: Record<string, unknown>) {
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/finance", { method: "POST", headers: { "Content-Type": "application/json", "x-mizan-locale": locale }, body: JSON.stringify(body) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || t("تعذر حفظ التغييرات", "Could not save changes"));
      setData(result); setDataVersion((version) => version + 1); setNotice(body.action === "import.commit" ? t("تم استيراد {imported}، وتجاوز {skipped} من المكررات", "Imported {imported}; skipped {skipped} duplicates", { imported: result.imported ?? 0, skipped: result.skipped ?? 0 }) : t("تم حفظ التغييرات بنجاح", "Your changes have been saved"));
    } catch (err) { const message = err instanceof Error ? err.message : String(err); setError(message); throw err; } finally { setBusy(false); }
  }
  const activeSection = nav.find((item) => item[0] === section);
  const title = section === "settings" ? t("الإعدادات", "Settings") : activeSection ? t(activeSection[1], activeSection[2]) : t("نظرة عامة", "Overview");
  const ctx: Ctx | null = data ? { data, locale, t, currency, setCurrency, mutate, open: setDialog, busy } : null;
  async function logout() {
    setBusy(true); setError("");
    try {
      const response = await fetch(data?.demo ? "/api/demo/exit" : "/api/auth/sign-out", { method: "POST", headers: { "Content-Type": "application/json", "x-mizan-locale": locale }, body: "{}" });
      if (!response.ok) throw new Error(t("تعذر تسجيل الخروج. حاول مرة أخرى.", "Unable to sign out. Please try again."));
      router.push("/"); router.refresh();
    } catch (err) { setError(err instanceof Error ? err.message : String(err)); } finally { setBusy(false); }
  }
  return <div className="finance-app" dir={isRtl(locale) ? "rtl" : "ltr"}>
    <a className="skip-link" href="#main-content">{t("تخطي إلى المحتوى", "Skip to content")}</a>
    {menu && <button className="sidebar-backdrop" aria-label={t("إغلاق القائمة", "Close menu")} onClick={() => setMenu(false)} />}
    <aside ref={sidebarRef} className={`finance-sidebar ${menu ? "mobile-open" : ""}`} role={menu ? "dialog" : undefined} aria-modal={menu || undefined} aria-label={t("مساحتي المالية", "My financial workspace")}>
      <button className="drawer-close icon-button" onClick={() => setMenu(false)} aria-label={t("إغلاق القائمة", "Close menu")}><X size={21} /></button>
      <Link href="/" className="app-brand"><span className="brand-symbol">m<span>·</span></span><span><strong>{t("ميزان", "mizan")}</strong><small>{t("مالٌ في توازن", "FINANCE, IN BALANCE")}</small></span></Link>
      <div className="workspace-label"><span className="workspace-icon"><Wallet size={16} /></span><span>{t("مساحتي المالية", "Personal workspace")}<small>{t("حسابك الشخصي", "Personal account")}</small></span><ChevronLeft size={14} /></div>
      <p className="nav-caption">{t("إدارة أموالك", "YOUR WORKSPACE")}</p>
      <nav aria-label={t("التنقل الرئيسي", "Main navigation")}>{nav.map(([key, ar, en, Icon]) => <Link key={key} href={`/app/${key}`} data-testid={`nav-${key}`} onClick={() => setMenu(false)} className={section === key ? "nav-link active" : "nav-link"} aria-current={section === key ? "page" : undefined}><Icon size={19} /><span>{t(ar, en)}</span>{key === "insights" && <i className="nav-dot" />}</Link>)}</nav>
      <div className="sidebar-bottom"><Link data-testid="nav-settings" href="/app/settings" onClick={() => setMenu(false)} className={section === "settings" ? "nav-link active" : "nav-link"}><Settings2 size={18} />{t("الإعدادات", "Settings")}</Link><button className="nav-link sidebar-signout" disabled={busy} onClick={() => void logout()}><LogOut size={18} />{t("تسجيل الخروج", "Sign out")}</button><button className="profile-switch" onClick={() => router.push("/app/settings")}><span className="avatar">{data?.profile.name?.slice(0, 1) || t("م", "M")}</span><span><strong>{data?.profile.name || t("حسابي", "My account")}</strong><small>{data?.demo ? t("مساحة تجريبية خاصة", "Private demo workspace") : t("الحساب الشخصي", "Personal account")}</small></span><MoreHorizontal size={18} /></button></div>
    </aside>
    <div className="finance-main">
      <header className="app-topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" onClick={() => setMenu(true)} aria-label={t("فتح القائمة", "Open menu")}><Menu size={21} /></button><span>{t("مساحتي المالية", "My workspace")}</span><span className="crumb-slash">/</span><strong>{title}</strong></div><div className="topbar-actions"><LanguageSelect compact /><button className="icon-button" onClick={() => setTheme(theme === "light" ? "dark" : "light")} aria-label={t("تغيير المظهر", "Toggle theme")} data-testid="theme-toggle">{theme === "light" ? <Moon size={18} /> : <Sun size={18} />}</button><Link className="notification-button icon-button" href="/app/recurring" aria-label={t("الالتزامات القادمة", "Upcoming commitments")}><Bell size={19} />{data?.recurring.some((r) => r.active && r.nextDate <= today(ctx?.data.profile.timezone)) && <i />}</Link><button className="icon-button" onClick={() => void logout()} aria-label={t("تسجيل الخروج", "Sign out")}><LogOut size={18} /></button></div></header>
      {data?.demo && <div className="demo-banner"><span><Info size={14} />{t("أنت في مساحة تجريبية خاصة — بيانات توضيحية يمكنك تعديلها.", "Your private demo workspace — explore and edit the sample data.")}</span><Link href="/register">{t("أنشئ حسابك", "Create your account")} <ArrowUpRight size={14} /></Link></div>}
      <main id="main-content" className="app-content">
        {error && <div className="feedback error" role="alert"><AlertCircle size={18} /><span>{error}</span><button className="text-button" onClick={() => void refresh()}>{t("أعد المحاولة", "Try again")}</button></div>}
        {!data ? <div className={error ? "load-failed" : "loading-page"} aria-busy={!error}><div className="skeleton skeleton-title" /><div className="stats-grid">{[1, 2, 3, 4].map((i) => <div key={i} className="skeleton skeleton-card" />)}</div><div className="skeleton skeleton-chart" /><p>{t("جارٍ تحميل حساباتك…", "Loading your accounts…")}</p></div> : ctx && <>
          <div className="page-heading"><div><span className="eyebrow">{section === "dashboard" ? t("ملخص حساباتك", "Account summary") : t("إدارة حساباتك", "Your workspace")}</span><h1>{section === "dashboard" ? <>{t("أهلًا، ", "Hello, ")}{data.profile.name.split(" ")[0]}<span className="greeting-dot">.</span></> : title}</h1><p>{section === "dashboard" ? t("أرصدتك ومعاملاتك والتزاماتك لهذا الشهر.", "Your balances, transactions and upcoming payments.") : sectionDescription(section, t)}</p></div><div className="heading-actions">{["dashboard", "reports", "insights", "simulator"].includes(section) && <label className="currency-picker"><span className="sr-only">{t("عملة العرض", "Display currency")}</span><select value={currency} onChange={(e) => setCurrency(e.target.value as Currency)}>{currencyOptions.map((o) => <option key={o.value}>{o.value}</option>)}</select></label>}<button className="btn btn-primary" data-testid="add-transaction" onClick={() => setDialog(transactionDialog(ctx))} disabled={!data.accounts.length}><Plus size={18} />{t("إضافة معاملة", "Add transaction")}</button></div></div>
          {section === "dashboard" && <Dashboard ctx={ctx} />}
          {section === "transactions" && <Transactions ctx={ctx} />}
          {section === "accounts" && <Accounts ctx={ctx} />}
          {section === "budgets" && <Budgets ctx={ctx} />}
          {section === "goals" && <Goals ctx={ctx} />}
          {section === "recurring" && <RecurringView ctx={ctx} />}
          {section === "reports" && <Reports ctx={ctx} />}
          {section === "simulator" && <ScenarioSimulator key={`${currency}:${dataVersion}`} data={data} locale={locale} currency={currency} t={t} />}
          {section === "insights" && <Insights ctx={ctx} />}
          {section === "settings" && <Settings ctx={ctx} />}
          <footer className="app-footer"><span>© {new Date().getFullYear()} {t("ميزان لإدارة المال الشخصي", "Mizan Finance")}</span><span><ShieldCheck size={13} />{t("بياناتك تخصّك وحدك", "Your data belongs to you")}</span></footer>
        </>}
      </main>
      <nav className="mobile-bottom-nav" aria-label={t("التنقل السريع", "Quick navigation")}>{nav.slice(0, 4).map(([key, ar, en, Icon]) => <Link key={key} href={`/app/${key}`} className={section === key ? "active" : ""}><Icon size={19} /><span>{t(ar, en)}</span></Link>)}<button onClick={() => setMenu(true)}><Ellipsis size={19} /><span>{t("المزيد", "More")}</span></button></nav>
    </div>
    {notice && <div className="toast" role="status"><CheckCircle2 size={19} />{notice}<button aria-label={t("إغلاق", "Dismiss")} onClick={() => setNotice("")}><X size={15} /></button></div>}
    {dialog && ctx && <FormDialog key={`${dialog.action}-${String(dialog.extra?.id || "new")}`} spec={dialog} ctx={ctx} close={() => setDialog(null)} />}
  </div>;
}

function sectionDescription(section: string, t: T) { const descriptions: Record<string, [string, string]> = { simulator: ["قارن أثر الشراء على أموالك خلال 30 أو 60 أو 90 يومًا.", "Compare a purchase and daily spending over 30, 60 or 90 days."], transactions: ["كل حركة مالية، في صورة واضحة.", "Every money move, clearly in view."], accounts: ["أموالك موزّعة، وصورتها هنا متكاملة.", "Your money may live in different places. Its story lives here."], budgets: ["امنح كل مصروف مساحة، وكل شهر خطة.", "Give your spending a little structure."], goals: ["الأشياء التي تهمك، أقرب خطوة بخطوة.", "Make space for the things that matter."], recurring: ["اعرف ما هو قادم قبل موعده.", "Know what’s coming, before it arrives."], reports: ["افهم أنماطك المالية، بالأرقام.", "A clearer understanding of your money habits."], insights: ["ملاحظات محسوبة، مستندة إلى بياناتك.", "Thoughtful observations, grounded in your numbers."], settings: ["مساحتك، على طريقتك.", "Your workspace. Your preferences."] }; return t(...(descriptions[section] || ["", ""])); }

function FormDialog({ spec, ctx, close }: { spec: DialogSpec; ctx: Ctx; close: () => void }) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const [values, setValues] = useState<Record<string, string>>(() => {
    const initial = Object.fromEntries(spec.fields.map((f) => [f.key, spec.values?.[f.key] ?? f.options?.[0]?.value ?? ""]));
    const categories = spec.fields.find((f) => f.key === "categoryId")?.options;
    if (initial.kind && categories && !categories.some((c) => c.value === initial.categoryId && c.kind === initial.kind)) initial.categoryId = categories.find((c) => c.kind === initial.kind)?.value || "";
    return initial;
  });
  const [error, setError] = useState("");
  useEffect(() => { dialogRef.current?.showModal(); }, []);
  async function submit(e: React.FormEvent) {
    e.preventDefault(); setError("");
    try {
      const payload: Record<string, unknown> = { action: spec.action, ...spec.extra };
      spec.fields.forEach((field) => { payload[field.key] = field.type === "money" ? minor(values[field.key], ctx.locale) : values[field.key]; });
      if (payload.accountId && ["transaction.create", "transaction.update", "recurring.create", "recurring.update"].includes(spec.action)) payload.currency = ctx.data.accounts.find((a) => a.id === payload.accountId)?.currency;
      await ctx.mutate(payload); close();
    } catch (err) { setError(err instanceof Error ? err.message : String(err)); }
  }
  function change(key: string, value: string) { setValues((old) => { const next = { ...old, [key]: value }; if (key === "kind") next.categoryId = spec.fields.find((f) => f.key === "categoryId")?.options?.find((o) => o.kind === value)?.value || ""; return next; }); }
  return <dialog ref={dialogRef} className="finance-dialog" onCancel={close} onClick={(e) => { if (e.target === e.currentTarget) close(); }} aria-labelledby="dialog-title"><div className="dialog-inner"><div className="dialog-header"><h2 id="dialog-title">{spec.title}</h2><button className="icon-button" onClick={close} aria-label={ctx.t("إغلاق", "Close")}><X size={20} /></button></div>{spec.description && <p className="dialog-description">{spec.description}</p>}<form onSubmit={submit}><div className="dialog-fields">{spec.fields.map((field) => <label key={field.key} className={`form-field ${field.type === "textarea" ? "full-width" : ""}`}><span>{ctx.t(field.ar, field.en)}</span>{field.type === "select" ? <select name={field.key} value={values[field.key]} onChange={(e) => change(field.key, e.target.value)} required={field.required !== false}>{field.options?.filter((o) => field.key !== "categoryId" || !values.kind || o.kind === values.kind).map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select> : field.type === "textarea" ? <textarea name={field.key} value={values[field.key]} onChange={(e) => change(field.key, e.target.value)} required={field.required !== false} maxLength={5000} rows={4} /> : <input name={field.key} type={field.type === "money" ? "text" : field.type || "text"} inputMode={field.type === "money" ? "decimal" : undefined} value={values[field.key]} onChange={(e) => change(field.key, e.target.value)} required={field.required !== false} maxLength={field.type === "money" ? 14 : 200} placeholder={field.type === "money" ? major(0, ctx.locale) : undefined} />}</label>)}</div>{error && <p className="form-error" role="alert">{error}</p>}<div className="dialog-footer"><button type="button" className="btn btn-secondary" onClick={close}>{ctx.t("إلغاء", "Cancel")}</button><button className="btn btn-primary" type="submit" data-testid="modal-submit" disabled={ctx.busy}>{ctx.busy ? ctx.t("جارٍ الحفظ…", "Saving…") : <><Check size={17} />{ctx.t("حفظ", "Save")}</>}</button></div></form></div></dialog>;
}

function Panel({ title, subtitle, action, className = "", children }: { title: string; subtitle?: string; action?: React.ReactNode; className?: string; children: React.ReactNode }) { return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>{children}</section>; }
function Empty({ ctx, text, action }: { ctx: Ctx; text?: string; action?: React.ReactNode }) { return <div className="empty-state"><span><Wallet size={27} /></span><h3>{text || ctx.t("لا توجد بيانات بعد", "No records yet")}</h3><p>{ctx.t("أضف بياناتك الأولى لتبدأ متابعة تقدمك.", "Add your first records to start seeing your progress.")}</p>{action}</div>; }
function Progress({ value, label }: { value: number; label: string }) { return <div className={`progress-track ${value >= 100 ? "over-budget" : value >= 80 ? "near-budget" : ""}`} role="progressbar" aria-label={label} aria-valuenow={Math.round(Math.min(100, value))} aria-valuemin={0} aria-valuemax={100}><div style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>; }
function CategoryIcon({ kind, color }: { kind: string; color?: string }) { return <span className={`category-icon ${kind === "income" ? "income-icon" : ""}`} style={color ? { color, background: `color-mix(in srgb, ${color} 10%, var(--surface))` } : undefined}>{kind === "income" ? <ArrowDownLeft size={18} /> : <ArrowUpRight size={18} />}</span>; }
function QuietLink({ href, children }: { href: string; children: React.ReactNode }) { return <Link className="quiet-link" href={href}>{children}<ChevronLeft size={14} className="direction-arrow" /></Link>; }

function Dashboard({ ctx }: { ctx: Ctx }) {
  const { data, t, locale, currency } = ctx;
  const current = thisMonth(ctx.data.profile.timezone); const d = new Date(`${current}-01T12:00:00Z`); d.setUTCMonth(d.getUTCMonth() - 1); const previous = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
  const currentRows = data.transactions.filter((r) => r.currency === currency && r.date.startsWith(current));
  const previousRows = data.transactions.filter((r) => r.currency === currency && r.date.startsWith(previous));
  const income = sum(currentRows, "income"), expense = sum(currentRows, "expense");
  const total = data.accounts.filter((a) => a.currency === currency).reduce((n, a) => n + a.balance, 0);
  const accounts = data.accounts.filter((a) => a.currency === currency);
  const expenseDifference = expense - sum(previousRows, "expense");
  const savings = data.goals.filter((g) => g.currency === currency).reduce((n, g) => n + g.saved, 0);
  const breakdown = data.categories.filter((c) => c.kind === "expense").map((c) => ({ name: categoryLabel(data, c.id, locale), amount: currentRows.filter((r) => r.categoryId === c.id).reduce((n, r) => n + r.amount, 0), color: c.color })).filter((c) => c.amount).sort((a, b) => b.amount - a.amount);
  const due = data.recurring.filter((r) => r.active && r.currency === currency).sort((a, b) => a.nextDate.localeCompare(b.nextDate)).slice(0, 3);
  return <>
    <div className="dashboard-period"><span><span className="live-dot" />{new Intl.DateTimeFormat(localeTag(locale), { month: "long", year: "numeric", timeZone: data.profile.timezone }).format(new Date())}</span><span><CalendarDays size={14} />{t("هذا الشهر", "This month")}</span></div>
    <div className="stats-grid"><article className="stat-card wealth-card"><div className="stat-label"><span>{t("إجمالي الأرصدة", "Total balance")}</span><Wallet size={18} /></div><strong className="stat-value">{money(total, currency, locale)}</strong><div className="stat-foot"><span className="light-pill">{accounts.length} {t("حسابات", "accounts")}</span><span>{t("أموالك، في مكان واحد", "Your money, together")}</span></div><div className="wealth-orbits" aria-hidden="true"><i /><i /><i /></div></article><article className="stat-card"><div className="stat-label"><span>{t("الدخل الشهري", "Monthly income")}</span><span className="stat-icon positive"><ArrowDownLeft size={18} /></span></div><strong className="stat-value">{money(income, currency, locale)}</strong><div className="stat-foot"><span className="positive-text"><TrendingUp size={13} />{money(income - sum(previousRows, "income"), currency, locale)}</span><span>{t("عن الشهر الماضي", "vs. last month")}</span></div></article><article className="stat-card"><div className="stat-label"><span>{t("المصروفات", "Monthly expenses")}</span><span className="stat-icon expense"><ArrowUpRight size={18} /></span></div><strong className="stat-value">{money(expense, currency, locale)}</strong><div className="stat-foot"><span className={expenseDifference <= 0 ? "positive-text" : "warning-text"}>{expenseDifference <= 0 ? "↓" : "↑"} {money(Math.abs(expenseDifference), currency, locale)}</span><span>{t("عن الشهر الماضي", "vs. last month")}</span></div></article><article className="stat-card"><div className="stat-label"><span>{t("صافي التدفق", "Net cash flow")}</span><span className="stat-icon neutral"><ChartNoAxesCombined size={18} /></span></div><strong className="stat-value">{money(income - expense, currency, locale)}</strong><div className="stat-foot"><span className="positive-text">{t("الدخل − المصروفات", "Income − expenses")}</span></div></article></div>
    {data.accounts.some((a) => a.currency !== currency) && <p className="currency-note">{t("تُعرض كل عملة بشكل مستقل؛ اختر العملة أعلاه لعرض أرصدتها دون تحويل تقديري.", "Currencies are shown separately. Choose a currency above to view its balances without estimated conversion.")}</p>}
    <div className="dashboard-chart-grid"><Panel title={t("الدخل والمصروفات", "Income and expenses")} subtitle={t("الدخل والمصروفات خلال آخر ٦ أشهر", "Income and expenses over the last 6 months")} action={<div className="chart-legend"><span><i />{t("الدخل", "Income")}</span><span><i className="gold" />{t("المصروفات", "Expenses")}</span></div>}><CashflowChart rows={monthlyRows(data, currency)} currency={currency} locale={locale} /></Panel><Panel title={t("توزيع المصروفات", "Spending by category")} subtitle={t("توزيع إنفاق هذا الشهر", "This month’s spending breakdown")} action={<QuietLink href="/app/reports">{t("التقرير", "Report")}</QuietLink>}><SpendingChart rows={breakdown} currency={currency} locale={locale} /></Panel></div>
    <div className="dashboard-detail-grid"><Panel title={t("آخر المعاملات", "Recent transactions")} subtitle={t("آخر الحركات على حساباتك", "The latest activity across your accounts")} action={<QuietLink href="/app/transactions">{t("عرض الكل", "View all")}</QuietLink>}>{data.transactions.length ? <TransactionTable ctx={ctx} rows={[...data.transactions].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 5)} compact /> : <Empty ctx={ctx} />}</Panel><Panel title={t("الميزانيات الشهرية", "Monthly budgets")} subtitle={t("مساحة للإنفاق. مساحة للراحة.", "Room to spend. Room to breathe.")} action={<QuietLink href="/app/budgets">{t("التفاصيل", "Details")}</QuietLink>}>{data.budgets.filter((b) => b.month === current && b.currency === currency).length ? <div className="compact-budgets">{data.budgets.filter((b) => b.month === current && b.currency === currency).slice(0, 3).map((b) => { const ratio = b.spent / b.amount * 100; return <div key={b.id} className="budget-mini"><div><strong>{categoryLabel(data, b.categoryId, locale)}</strong><span>{Math.round(ratio)}%</span></div><Progress value={ratio} label={categoryLabel(data, b.categoryId, locale)} /><p><span>{money(b.spent, b.currency, locale)} <small>{t("من", "of")} {money(b.amount, b.currency, locale)}</small></span>{ratio >= 100 ? <span className="warning-text">{t("تم تجاوز الحد", "Over budget")}</span> : null}</p></div>; })}</div> : <Empty ctx={ctx} text={t("خطتك للشهر تبدأ هنا", "Your monthly plan starts here")} action={<button className="btn btn-secondary" onClick={() => ctx.open(budgetDialog(ctx))}>{t("إنشاء ميزانية", "Create a budget")}</button>} />}</Panel></div>
    <div className="dashboard-bottom-grid"><Panel title={t("أهداف الادخار", "Towards what matters")} subtitle={`${t("مخصّص لأهدافك", "Allocated to your goals")} · ${money(savings, currency, locale)}`} action={<QuietLink href="/app/goals">{t("كل الأهداف", "All goals")}</QuietLink>}><div className="dashboard-goals">{data.goals.filter((g) => g.currency === currency).slice(0, 2).map((g) => <div className="goal-mini" key={g.id}><span className="goal-symbol"><Target size={22} /></span><div><strong>{g.name}</strong><p>{money(g.saved, g.currency, locale)} <small>/ {money(g.target, g.currency, locale)}</small></p><Progress value={g.saved / g.target * 100} label={g.name} /></div><span className="goal-percent">{Math.round(g.saved / g.target * 100)}%</span></div>)}{!data.goals.filter((g) => g.currency === currency).length && <Empty ctx={ctx} action={<button className="btn btn-secondary" onClick={() => ctx.open(goalDialog(ctx))}>{t("أضف هدفًا", "Add a goal")}</button>} />}</div></Panel><Panel title={t("الالتزامات القادمة", "Upcoming payments")} subtitle={t("التزامات مجدولة، لم تُسجّل بعد", "Scheduled commitments, not yet recorded")} action={<QuietLink href="/app/recurring">{t("عرض الكل", "View all")}</QuietLink>}><div className="upcoming-list">{due.map((r) => <div key={r.id}><span className="date-tile"><strong>{r.nextDate.slice(8, 10)}</strong><small>{new Intl.DateTimeFormat(localeTag(locale), { month: "short" }).format(new Date(`${r.nextDate}T12:00:00`))}</small></span><span className="upcoming-name"><strong>{r.name}</strong><small>{r.nextDate <= today(ctx?.data.profile.timezone) ? t("مستحق للتسجيل", "Due to record") : t("مجدول", "Scheduled")}</small></span><strong>{money(r.amount, r.currency, locale)}</strong></div>)}{!due.length && <p className="empty-inline">{t("لا توجد التزامات مجدولة. مساحة للتنفس.", "Nothing scheduled. A little breathing room.")}</p>}</div></Panel></div>
  </>;
}

function TransactionTable({ ctx, rows, compact = false }: { ctx: Ctx; rows: Transaction[]; compact?: boolean }) { return <div className="table-scroll"><table className="transaction-table"><thead><tr><th>{ctx.t("المعاملة", "Transaction")}</th><th>{ctx.t("الحساب", "Account")}</th><th>{ctx.t("التاريخ", "Date")}</th><th>{ctx.t("المبلغ", "Amount")}</th>{!compact && <th><span className="sr-only">{ctx.t("الإجراءات", "Actions")}</span></th>}</tr></thead><tbody>{rows.map((row) => { const cat = ctx.data.categories.find((c) => c.id === row.categoryId); return <tr key={row.id}><td><div className="transaction-name"><CategoryIcon kind={row.kind} color={cat?.color} /><span><strong>{row.note || categoryLabel(ctx.data, row.categoryId, ctx.locale)}</strong><small>{categoryLabel(ctx.data, row.categoryId, ctx.locale)}</small></span></div></td><td><span className="account-tag">{ctx.data.accounts.find((a) => a.id === row.accountId)?.name}</span></td><td className="muted-cell">{dateLabel(row.date, ctx.locale, ctx.data.profile.timezone)}</td><td className={`amount-cell ${row.kind === "income" ? "positive-text" : ""}`}><bdi>{row.kind === "income" ? "+" : "−"}{money(row.amount, row.currency, ctx.locale)}</bdi></td>{!compact && <td><div className="row-actions"><button className="icon-button" aria-label={ctx.t("تعديل المعاملة", "Edit transaction")} onClick={() => ctx.open(transactionDialog(ctx, row))}><Pencil size={15} /></button><DeleteButton ctx={ctx} label={ctx.t("حذف المعاملة", "Delete transaction")} action="transaction.delete" id={row.id} /></div></td>}</tr>; })}</tbody></table></div>; }
function DeleteButton({ ctx, label, action, id }: { ctx: Ctx; label: string; action: string; id: string }) { const [confirm, setConfirm] = useState(false); return confirm ? <span className="inline-confirm"><button disabled={ctx.busy} className="text-button danger-text" onClick={() => void ctx.mutate({ action, id }).then(() => setConfirm(false)).catch(() => {})}>{ctx.t("تأكيد الحذف", "Confirm delete")}</button><button className="icon-button" aria-label={ctx.t("إلغاء", "Cancel")} onClick={() => setConfirm(false)}><X size={14} /></button></span> : <button className="icon-button" aria-label={label} onClick={() => setConfirm(true)}><Trash2 size={15} /></button>; }

function Transactions({ ctx }: { ctx: Ctx }) {
  const [query, setQuery] = useState(""); const [kind, setKind] = useState(""); const [account, setAccount] = useState(""); const [category, setCategory] = useState(""); const [from, setFrom] = useState(""); const [to, setTo] = useState(""); const [sort, setSort] = useState("date-desc"); const [page, setPage] = useState(1); const [importOpen, setImportOpen] = useState(false);
  const rows = useMemo(() => ctx.data.transactions.filter((r) => (!query || `${r.note} ${categoryLabel(ctx.data, r.categoryId, ctx.locale)}`.toLowerCase().includes(query.toLowerCase())) && (!kind || r.kind === kind) && (!account || r.accountId === account) && (!category || r.categoryId === category) && (!from || r.date >= from) && (!to || r.date <= to)).sort((a, b) => sort === "amount-desc" ? b.amount - a.amount : sort === "date-asc" ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date)), [ctx.data, ctx.locale, query, kind, account, category, from, to, sort]);
  const pages = Math.max(1, Math.ceil(rows.length / 10)); const currentPage = Math.min(page, pages);
  function filter(setter: (v: string) => void, value: string) { setter(value); setPage(1); }
  return <><div className="section-toolbar"><div className="segmented"><button className={!kind ? "selected" : ""} onClick={() => filter(setKind, "")}>{ctx.t("كل المعاملات", "All transactions")}</button><button className={kind === "income" ? "selected" : ""} onClick={() => filter(setKind, "income")}>{ctx.t("الدخل", "Income")}</button><button className={kind === "expense" ? "selected" : ""} onClick={() => filter(setKind, "expense")}>{ctx.t("المصروفات", "Expenses")}</button></div><div className="toolbar-buttons"><button className="btn btn-secondary" onClick={() => setImportOpen(!importOpen)}><Upload size={16} />{ctx.t("استيراد CSV", "Import CSV")}</button><a className="btn btn-secondary" href="/api/export?format=csv"><Download size={16} />{ctx.t("تصدير CSV", "Export CSV")}</a></div></div>{importOpen && <ImportPanel data={ctx.data} locale={ctx.locale} t={ctx.t} mutate={ctx.mutate} close={() => setImportOpen(false)} />}
  <section className="panel"><div className="transaction-filters"><label className="search-field"><Search size={17} /><input aria-label={ctx.t("البحث في المعاملات", "Search transactions")} placeholder={ctx.t("ابحث عن معاملة…", "Search transactions…")} value={query} onChange={(e) => filter(setQuery, e.target.value)} /></label><select aria-label={ctx.t("تصفية الحساب", "Filter account")} value={account} onChange={(e) => filter(setAccount, e.target.value)}><option value="">{ctx.t("جميع الحسابات", "All accounts")}</option>{accountOptions(ctx.data).map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select><select aria-label={ctx.t("تصفية التصنيف", "Filter category")} value={category} onChange={(e) => filter(setCategory, e.target.value)}><option value="">{ctx.t("كل التصنيفات", "All categories")}</option>{categoryOptions(ctx.data, ctx.locale).map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select><select aria-label={ctx.t("ترتيب", "Sort")} value={sort} onChange={(e) => filter(setSort, e.target.value)}><option value="date-desc">{ctx.t("الأحدث أولًا", "Newest first")}</option><option value="date-asc">{ctx.t("الأقدم أولًا", "Oldest first")}</option><option value="amount-desc">{ctx.t("الأعلى مبلغًا", "Largest amount")}</option></select><label className="inline-date">{ctx.t("من", "From")}<input type="date" value={from} onChange={(e) => filter(setFrom, e.target.value)} /></label><label className="inline-date">{ctx.t("إلى", "To")}<input type="date" value={to} onChange={(e) => filter(setTo, e.target.value)} /></label></div>{rows.length ? <TransactionTable ctx={ctx} rows={rows.slice((currentPage - 1) * 10, currentPage * 10)} /> : <Empty ctx={ctx} text={ctx.t("لا توجد معاملات مطابقة", "No matching transactions")} />}<div className="pagination"><span>{rows.length} {ctx.t("معاملة", "transactions")}</span><div><button className="icon-button" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)} aria-label={ctx.t("الصفحة السابقة", "Previous page")}>{isRtl(ctx.locale) ? <ChevronRight size={17} /> : <ChevronLeft size={17} />}</button><span>{currentPage} / {pages}</span><button className="icon-button" disabled={currentPage === pages} onClick={() => setPage(currentPage + 1)} aria-label={ctx.t("الصفحة التالية", "Next page")}>{isRtl(ctx.locale) ? <ChevronLeft size={17} /> : <ChevronRight size={17} />}</button></div></div></section></>;
}

function Accounts({ ctx }: { ctx: Ctx }) {
  const addAccount = () => ctx.open({ title: ctx.t("حساب مالي جديد", "New financial account"), action: "account.create", values: { currency: ctx.currency, openingBalance: "0" }, fields: [{ key: "name", ar: "اسم الحساب", en: "Account name" }, { key: "type", ar: "نوع الحساب", en: "Account type", type: "select", options: [{ value: "bank", label: ctx.t("بنك يدوي", "Manual bank") }, { value: "cash", label: ctx.t("نقد", "Cash") }, { value: "wallet", label: ctx.t("محفظة", "Wallet") }] }, { key: "currency", ar: "العملة", en: "Currency", type: "select", options: currencyOptions }, { key: "openingBalance", ar: "الرصيد الافتتاحي", en: "Opening balance", type: "money" }] });
  const transfer = () => ctx.open({ title: ctx.t("تحويل بين الحسابات", "Transfer between accounts"), action: "transfer.create", description: ctx.t("التحويل متاح بين حسابين بالعملة نفسها. لا يُحتسب دخلًا أو مصروفًا.", "Transfers are available between accounts in the same currency. They do not count as income or expenses."), values: { date: today(ctx?.data.profile.timezone), toAccountId: ctx.data.accounts[1]?.id || "" }, fields: [{ key: "fromAccountId", ar: "من حساب", en: "From account", type: "select", options: accountOptions(ctx.data) }, { key: "toAccountId", ar: "إلى حساب", en: "To account", type: "select", options: accountOptions(ctx.data) }, { key: "amount", ar: "المبلغ", en: "Amount", type: "money" }, { key: "date", ar: "التاريخ", en: "Date", type: "date" }, { key: "note", ar: "ملاحظة", en: "Note", required: false }] });
  return <><div className="section-toolbar"><p className="subtle-note"><ShieldCheck size={16} />{ctx.t("حسابات يدوية — أنت تتحكم بالبيانات", "Manual accounts — you’re in control of the data")}</p><div className="toolbar-buttons"><button className="btn btn-secondary" onClick={transfer} disabled={ctx.data.accounts.length < 2}><ArrowLeftRight size={16} />{ctx.t("تحويل", "Transfer")}</button><button className="btn btn-primary" onClick={addAccount}><Plus size={16} />{ctx.t("إضافة حساب", "Add account")}</button></div></div><div className="accounts-grid">{ctx.data.accounts.map((a, index) => <article key={a.id} className={`account-card ${index % 3 === 0 ? "account-card-dark" : ""}`}><div><span className="account-card-icon"><Wallet size={23} /></span><span className="account-currency">{a.currency}</span></div><p>{a.name}</p><strong>{money(a.balance, a.currency, ctx.locale)}</strong><div className="account-card-bottom"><span>{a.type === "bank" ? ctx.t("حساب بنكي يدوي", "Manual bank account") : a.type === "cash" ? ctx.t("نقد", "Cash") : ctx.t("محفظة", "Wallet")}</span><span>•••• {a.id.slice(-4).toUpperCase()}</span></div><small>{ctx.t("الرصيد الافتتاحي", "Opening balance")}: {money(a.openingBalance, a.currency, ctx.locale)}</small></article>)}</div><div className="info-strip"><CircleHelp size={19} /><span>{ctx.t("تُعرض العملات منفصلة. لا نجمع أرصدة ILS وUSD وEUR دون سعر تحويل معلوم ومؤرّخ.", "Currencies stay separate. ILS, USD and EUR balances are never combined without a known, dated exchange rate.")}</span></div><Panel title={ctx.t("سجل التحويلات", "Transfer history")} subtitle={ctx.t("حركة داخلية لا تغيّر إجمالي أموالك", "Internal movements that preserve your total balance")}>{ctx.data.transfers.length ? <div className="table-scroll"><table><thead><tr><th>{ctx.t("من", "From")}</th><th>{ctx.t("إلى", "To")}</th><th>{ctx.t("المبلغ", "Amount")}</th><th>{ctx.t("التاريخ", "Date")}</th></tr></thead><tbody>{ctx.data.transfers.map((r) => <tr key={r.id}><td>{ctx.data.accounts.find((a) => a.id === r.fromAccountId)?.name}</td><td>{ctx.data.accounts.find((a) => a.id === r.toAccountId)?.name}</td><td>{money(r.amount, ctx.data.accounts.find((a) => a.id === r.fromAccountId)?.currency || "ILS", ctx.locale)}</td><td>{dateLabel(r.date, ctx.locale, ctx.data.profile.timezone)}</td></tr>)}</tbody></table></div> : <Empty ctx={ctx} text={ctx.t("لا توجد تحويلات بعد", "No transfers yet")} />}</Panel></>;
}

function Budgets({ ctx }: { ctx: Ctx }) {
  const [month, setMonth] = useState(thisMonth(ctx.data.profile.timezone)); const budgets = ctx.data.budgets.filter((b) => b.month === month);
  return <><div className="section-toolbar"><label className="inline-date">{ctx.t("الشهر", "Month")}<input type="month" value={month} onChange={(e) => setMonth(e.target.value)} /></label><button className="btn btn-primary" data-testid="add-budget" onClick={() => ctx.open(budgetDialog(ctx))}><Plus size={17} />{ctx.t("إنشاء ميزانية", "Create budget")}</button></div>{budgets.length ? <div className="budget-grid">{budgets.map((b) => { const ratio = b.spent / b.amount * 100; return <article className="panel budget-card" key={b.id}><div className="budget-card-top"><span className="category-icon"><Layers3 size={20} /></span><DeleteButton ctx={ctx} action="budget.delete" id={b.id} label={ctx.t("حذف الميزانية", "Delete budget")} /></div><h2>{categoryLabel(ctx.data, b.categoryId, ctx.locale)}</h2><p>{b.month} · {b.currency}</p><div className="budget-amount"><strong>{money(b.spent, b.currency, ctx.locale)}</strong><span>{ctx.t("من", "of")} {money(b.amount, b.currency, ctx.locale)}</span></div><Progress value={ratio} label={categoryLabel(ctx.data, b.categoryId, ctx.locale)} /><div className="budget-status"><span className={ratio >= 80 ? "warning-text" : "positive-text"}>{ratio >= 100 ? ctx.t("تجاوزت الحد", "Over budget") : ratio >= 80 ? ctx.t("اقتربت من الحد", "Approaching limit") : ctx.t("ضمن الميزانية", "On track")}</span><strong>{Math.round(ratio)}%</strong></div><div className="budget-remaining"><span>{b.amount - b.spent >= 0 ? ctx.t("متبقٍ", "Remaining") : ctx.t("تجاوز", "Over by")}</span><strong>{money(Math.abs(b.amount - b.spent), b.currency, ctx.locale)}</strong></div></article>; })}</div> : <Panel title={ctx.t("خطّة تستحق البداية", "A plan worth starting")}><Empty ctx={ctx} text={ctx.t("لم تحدد ميزانية لهذا الشهر بعد", "No budgets for this month yet")} action={<button className="btn btn-primary" onClick={() => ctx.open(budgetDialog(ctx))}>{ctx.t("إنشاء أول ميزانية", "Create your first budget")}</button>} /></Panel>}</>;
}

function Goals({ ctx }: { ctx: Ctx }) { return <><div className="section-toolbar"><p className="subtle-note"><Target size={17} />{ctx.t("تخصيص أموال، وليس مصروفات", "Allocations, not expenses")}</p><button className="btn btn-primary" data-testid="add-goal" onClick={() => ctx.open(goalDialog(ctx))}><Plus size={17} />{ctx.t("هدف جديد", "New goal")}</button></div>{ctx.data.goals.length ? <div className="goals-grid">{ctx.data.goals.map((g, index) => <article className="panel goal-card" key={g.id}><div className={`goal-card-art goal-art-${index % 3}`}><Target size={65} strokeWidth={1} /><span>{String(index + 1).padStart(2, "0")}</span></div><div className="goal-card-body"><div className="goal-title"><h2>{g.name}</h2><DeleteButton ctx={ctx} label={ctx.t("حذف الهدف", "Delete goal")} action="goal.delete" id={g.id} /></div><p><CalendarDays size={14} />{ctx.t("الهدف بحلول", "Target by")} {dateLabel(g.deadline, ctx.locale, ctx.data.profile.timezone)}</p><div className="goal-amount"><strong>{money(g.saved, g.currency, ctx.locale)}</strong><span>{Math.round(g.saved / g.target * 100)}%</span></div><Progress value={g.saved / g.target * 100} label={g.name} /><div className="goal-target">{ctx.t("من أصل", "of")} {money(g.target, g.currency, ctx.locale)}</div><button className="btn btn-secondary full-width" onClick={() => ctx.open(contributionDialog(ctx, g.id))}><Plus size={16} />{ctx.t("إضافة مساهمة", "Add contribution")}</button></div></article>)}</div> : <Panel title={ctx.t("حلمك القادم يبدأ من هنا", "Your next goal begins here")}><Empty ctx={ctx} action={<button className="btn btn-primary" onClick={() => ctx.open(goalDialog(ctx))}>{ctx.t("أضف هدفًا", "Add a goal")}</button>} /></Panel>}<div className="info-strip"><PiggyBank size={20} /><span>{ctx.t("تظل المساهمات جزءًا من رصيد حساباتك. يُسجّل التخصيص للهدف دون إنشاء مصروف أو خصم المال مرتين.", "Contributions remain part of your account balances. Goal allocations never create an expense or deduct your money twice.")}</span></div>{ctx.data.contributions.length > 0 && <Panel title={ctx.t("مساهماتك الأخيرة", "Your recent contributions")}><div className="table-scroll"><table><thead><tr><th>{ctx.t("الهدف", "Goal")}</th><th>{ctx.t("الحساب", "Account")}</th><th>{ctx.t("المبلغ", "Amount")}</th><th>{ctx.t("التاريخ", "Date")}</th></tr></thead><tbody>{ctx.data.contributions.slice(-10).reverse().map((r) => <tr key={r.id}><td>{ctx.data.goals.find((g) => g.id === r.goalId)?.name}</td><td>{ctx.data.accounts.find((a) => a.id === r.accountId)?.name}</td><td>{money(r.amount, ctx.data.goals.find((g) => g.id === r.goalId)?.currency || "ILS", ctx.locale)}</td><td>{dateLabel(r.date, ctx.locale, ctx.data.profile.timezone)}</td></tr>)}</tbody></table></div></Panel>}</>; }

function RecurringView({ ctx }: { ctx: Ctx }) {
  function recurringDialog(id?: string) { const r = ctx.data.recurring.find((item) => item.id === id); ctx.open({ title: r ? ctx.t("تعديل الجدولة", "Edit schedule") : ctx.t("معاملة متكررة جديدة", "New recurring transaction"), action: r ? "recurring.update" : "recurring.create", extra: r ? { id: r.id } : {}, description: ctx.t("المجدول لا يغيّر الرصيد. استخدم «تسجيل المستحقات» لترحيل العمليات المستحقة مرة واحدة فقط.", "Scheduled items do not affect balances. Use ‘Record due items’ to post due occurrences exactly once."), values: r ? { name: r.name, kind: r.kind, accountId: r.accountId, categoryId: r.categoryId, amount: major(r.amount, ctx.locale), frequency: r.frequency, nextDate: r.nextDate } : { kind: "expense", nextDate: today(ctx?.data.profile.timezone), frequency: "monthly" }, fields: [{ key: "name", ar: "اسم الاشتراك أو المعاملة", en: "Subscription or transaction name" }, { key: "kind", ar: "النوع", en: "Type", type: "select", options: [{ value: "expense", label: ctx.t("مصروف", "Expense") }, { value: "income", label: ctx.t("دخل", "Income") }] }, { key: "accountId", ar: "الحساب", en: "Account", type: "select", options: accountOptions(ctx.data) }, { key: "categoryId", ar: "التصنيف", en: "Category", type: "select", options: categoryOptions(ctx.data, ctx.locale) }, { key: "amount", ar: "المبلغ", en: "Amount", type: "money" }, { key: "frequency", ar: "التكرار", en: "Frequency", type: "select", options: [{ value: "monthly", label: ctx.t("شهريًا", "Monthly") }, { value: "weekly", label: ctx.t("أسبوعيًا", "Weekly") }, { value: "yearly", label: ctx.t("سنويًا", "Yearly") }] }, { key: "nextDate", ar: "الاستحقاق القادم", en: "Next due date", type: "date" }] }); }
  const due = ctx.data.recurring.filter((r) => r.active && r.nextDate <= today(ctx?.data.profile.timezone));
  return <><div className="section-toolbar"><span className="subtle-note"><CalendarDays size={17} />{due.length} {ctx.t("جدولة مستحقة للتسجيل", "schedules due to record")}</span><div className="toolbar-buttons"><button className="btn btn-secondary" disabled={ctx.busy || !due.length} onClick={() => void ctx.mutate({ action: "recurring.process" }).catch(() => {})}><CheckCircle2 size={16} />{ctx.t("تسجيل المستحقات", "Record due items")}</button><button className="btn btn-primary" onClick={() => recurringDialog()}><Plus size={17} />{ctx.t("معاملة متكررة", "New recurring item")}</button></div></div><div className="info-strip"><CalendarDays size={19} /><span>{ctx.t("المواعيد أدناه مجدولة وليست مصروفات فعلية. التسجيل يتم عند الضغط على «تسجيل المستحقات»؛ إعادة الضغط لا تكرر المعاملات.", "These are scheduled items, not recorded transactions. Due occurrences post when you select ‘Record due items’; repeating the action never duplicates them.")}</span></div><Panel title={ctx.t("جدول التزاماتك", "Your commitments")} subtitle={ctx.t("صورة مسبقة لما هو قادم", "A little foresight for the days ahead")}>{ctx.data.recurring.length ? <div className="table-scroll"><table><thead><tr><th>{ctx.t("الاسم", "Name")}</th><th>{ctx.t("المبلغ", "Amount")}</th><th>{ctx.t("الاستحقاق", "Due date")}</th><th>{ctx.t("الحالة", "Status")}</th><th>{ctx.t("الإجراءات", "Actions")}</th></tr></thead><tbody>{ctx.data.recurring.map((r) => <tr key={r.id}><td><div className="transaction-name"><span className="category-icon"><CreditCard size={18} /></span><span><strong>{r.name}</strong><small>{r.frequency === "monthly" ? ctx.t("شهريًا", "Monthly") : r.frequency === "weekly" ? ctx.t("أسبوعيًا", "Weekly") : ctx.t("سنويًا", "Yearly")} · {categoryLabel(ctx.data, r.categoryId, ctx.locale)}</small></span></div></td><td className="amount-cell">{money(r.amount, r.currency, ctx.locale)}</td><td>{dateLabel(r.nextDate, ctx.locale, ctx.data.profile.timezone)}</td><td><span className={`status-pill ${!r.active ? "paused" : r.nextDate <= today(ctx?.data.profile.timezone) ? "due" : ""}`}>{!r.active ? ctx.t("متوقف", "Paused") : r.nextDate <= today(ctx?.data.profile.timezone) ? ctx.t("مستحق، غير مسجّل", "Due, unrecorded") : ctx.t("مجدول", "Scheduled")}</span></td><td><div className="row-actions"><button className="icon-button" onClick={() => recurringDialog(r.id)} aria-label={ctx.t("تعديل", "Edit")}><Pencil size={16} /></button><button className="icon-button" disabled={ctx.busy} aria-label={r.active ? ctx.t("إيقاف", "Pause") : ctx.t("استئناف", "Resume")} onClick={() => void ctx.mutate({ action: "recurring.update", id: r.id, active: !r.active }).catch(() => {})}>{r.active ? <Pause size={16} /> : <Play size={16} />}</button></div></td></tr>)}</tbody></table></div> : <Empty ctx={ctx} text={ctx.t("لا توجد معاملات متكررة", "No recurring transactions yet")} />}</Panel></>;
}

function Reports({ ctx }: { ctx: Ctx }) {
  const [from, setFrom] = useState(`${thisMonth(ctx.data.profile.timezone)}-01`); const [to, setTo] = useState(today(ctx?.data.profile.timezone)); const [account, setAccount] = useState("");
  const activeAccount = ctx.data.accounts.some((a) => a.id === account && a.currency === ctx.currency) ? account : "";
  const rows = ctx.data.transactions.filter((r) => r.currency === ctx.currency && (!activeAccount || r.accountId === activeAccount) && r.date >= from && r.date <= to);
  const income = sum(rows, "income"), expense = sum(rows, "expense");
  const breakdown = ctx.data.categories.filter((c) => c.kind === "expense").map((c) => ({ name: categoryLabel(ctx.data, c.id, ctx.locale), amount: rows.filter((r) => r.categoryId === c.id).reduce((n, r) => n + r.amount, 0), color: c.color })).filter((r) => r.amount > 0).sort((a, b) => b.amount - a.amount);
  const trend = Array.from(new Set(rows.map((r) => r.date.slice(0, 7)))).sort().map((key) => ({ key, income: sum(rows.filter((r) => r.date.startsWith(key)), "income") / 100, expense: sum(rows.filter((r) => r.date.startsWith(key)), "expense") / 100 }));
  return <div className="printable-report"><div className="section-toolbar report-filters"><div className="toolbar-buttons"><label className="inline-date">{ctx.t("من", "From")}<input type="date" value={from} onChange={(e) => setFrom(e.target.value)} /></label><label className="inline-date">{ctx.t("إلى", "To")}<input type="date" value={to} onChange={(e) => setTo(e.target.value)} /></label><select aria-label={ctx.t("الحساب", "Account")} value={activeAccount} onChange={(e) => setAccount(e.target.value)}><option value="">{ctx.t("كل الحسابات", "All accounts")}</option>{accountOptions(ctx.data, ctx.currency).map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select></div><div className="toolbar-buttons"><a className="btn btn-secondary" href={`/api/export?format=csv&from=${from}&to=${to}&currency=${ctx.currency}${activeAccount ? `&accountId=${activeAccount}` : ""}`}><Download size={16} />CSV</a><button className="btn btn-primary" data-testid="print-report" onClick={() => window.print()}><FileText size={16} />{ctx.t("طباعة / PDF", "Print / PDF")}</button></div></div><div className="report-title"><h2>{ctx.t("تقرير ميزان المالي", "Mizan financial report")}</h2><p>{from} — {to} · {ctx.currency} · {ctx.data.profile.name}</p></div><div className="report-stats"><article><span>{ctx.t("إجمالي الدخل", "Total income")}</span><strong className="positive-text">{money(income, ctx.currency, ctx.locale)}</strong></article><article><span>{ctx.t("إجمالي المصروفات", "Total expenses")}</span><strong>{money(expense, ctx.currency, ctx.locale)}</strong></article><article><span>{ctx.t("صافي التدفق", "Net cash flow")}</span><strong>{money(income - expense, ctx.currency, ctx.locale)}</strong></article><article><span>{ctx.t("عدد المعاملات", "Transactions")}</span><strong>{rows.length}</strong></article></div>{from > to && <p role="alert" className="form-error">{ctx.t("تاريخ البداية يجب أن يسبق النهاية", "Start date must precede end date")}</p>}<div className="dashboard-chart-grid"><Panel title={ctx.t("الدخل مقابل الإنفاق", "Income versus spending")} subtitle={`${from} — ${to}`}><CashflowChart rows={trend.length ? trend : [{ key: thisMonth(ctx.data.profile.timezone), income: 0, expense: 0 }]} currency={ctx.currency} locale={ctx.locale} /></Panel><Panel title={ctx.t("توزيع المصروفات", "Spending breakdown")}><SpendingChart rows={breakdown} currency={ctx.currency} locale={ctx.locale} /></Panel></div><Panel title={ctx.t("مقارنة التصنيفات", "Category comparison")} subtitle={ctx.t("تفاصيل الأرقام المعروضة في الرسم", "The numbers behind the chart")}><div className="table-scroll"><table><thead><tr><th>{ctx.t("التصنيف", "Category")}</th><th>{ctx.t("المبلغ", "Amount")}</th><th>{ctx.t("النسبة من الإنفاق", "Share of spending")}</th></tr></thead><tbody>{breakdown.map((r) => <tr key={r.name}><td><span className="legend-name"><i style={{ background: r.color }} />{r.name}</span></td><td>{money(r.amount, ctx.currency, ctx.locale)}</td><td>{expense ? Math.round(r.amount / expense * 100) : 0}%</td></tr>)}</tbody></table>{!breakdown.length && <p className="empty-inline">{ctx.t("لا توجد مصروفات في الفترة المحددة", "No expenses in the selected period")}</p>}</div></Panel><p className="currency-note">{ctx.t("تقرير مبني على المعاملات المسجلة فقط. التحويلات الداخلية وتخصيص الأهداف مستثناة من الدخل والمصروفات.", "Based on recorded transactions only. Internal transfers and goal allocations are excluded from income and expenses.")}</p></div>;
}

function Insights({ ctx }: { ctx: Ctx }) {
  const month = thisMonth(ctx.data.profile.timezone); const d = new Date(`${month}-01T12:00:00Z`); d.setUTCMonth(d.getUTCMonth() - 1); const previous = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
  const insights = ctx.data.categories.filter((c) => c.kind === "expense").map((c) => { const current = ctx.data.transactions.filter((r) => r.currency === ctx.currency && r.categoryId === c.id && r.date.startsWith(month)).reduce((n, r) => n + r.amount, 0); const prior = ctx.data.transactions.filter((r) => r.currency === ctx.currency && r.categoryId === c.id && r.date.startsWith(previous)).reduce((n, r) => n + r.amount, 0); return { category: c, current, prior, change: current - prior }; }).filter((r) => r.current || r.prior).sort((a, b) => Math.abs(b.change) - Math.abs(a.change)).slice(0, 4);
  const newNote = () => ctx.open({ title: ctx.t("ملاحظة مالية جديدة", "New financial note"), action: "note.create", fields: [{ key: "title", ar: "العنوان", en: "Title" }, { key: "body", ar: "الملاحظة", en: "Note", type: "textarea" }] });
  return <><div className="info-strip"><Lightbulb size={20} /><span>{ctx.t("مقارنة {month} حتى اليوم مع كامل الشهر {previous}. هذه قراءة حسابية لبياناتك، وليست توصية استثمارية.", "Comparing {month} to date with the complete month {previous}. Calculated from your data; not investment advice.", { month: month, previous: previous })}</span></div><div className="insights-grid">{insights.map((i) => <article className="panel insight-card" key={i.category.id}><span className={`insight-symbol ${i.change > 0 ? "warm" : ""}`}>{i.change > 0 ? <ArrowUpRight size={23} /> : <ArrowDownLeft size={23} />}</span><span className="eyebrow">{categoryLabel(ctx.data, i.category.id, ctx.locale)}</span><h2>{i.change > 0 ? ctx.t("إنفاق أعلى هذا الشهر", "Spending is higher this month") : i.change < 0 ? ctx.t("إنفاق أقل هذا الشهر", "Spending is lower this month") : ctx.t("نفس مستوى الإنفاق", "Spending is unchanged")}</h2><p>{ctx.t("أنفقت {current} هذا الشهر، مقارنة بـ {prior} في الشهر الماضي.", "You spent {current} this month, compared with {prior} last month.", { current: money(i.current, ctx.currency, ctx.locale), prior: money(i.prior, ctx.currency, ctx.locale) })}</p><div className="insight-comparison"><strong>{i.change > 0 ? "+" : ""}{money(i.change, ctx.currency, ctx.locale)}</strong><span>{i.prior ? `${Math.round(i.change / i.prior * 100)}%` : ctx.t("لا توجد قاعدة مقارنة سابقة", "No previous baseline")}</span></div><small>{previous} → {month} · {ctx.currency}</small></article>)}</div>{!insights.length && <Panel title={ctx.t("كل رقم يحكي شيئًا", "Every number tells a story")}><Empty ctx={ctx} text={ctx.t("ستظهر الملاحظات بعد تسجيل مصروفاتك", "Your insights appear as you record expenses")} /></Panel>}<Panel title={ctx.t("دفترك المالي", "Your money journal")} subtitle={ctx.t("أفكار وخطط تستحق أن تتذكرها", "Thoughts and plans worth keeping")} action={<button className="btn btn-secondary" onClick={newNote}><Plus size={16} />{ctx.t("ملاحظة", "New note")}</button>}><div className="notes-grid">{ctx.data.notes.map((note) => <article className="journal-note" key={note.id}><div><FileText size={18} /><DeleteButton ctx={ctx} label={ctx.t("حذف الملاحظة", "Delete note")} action="note.delete" id={note.id} /></div><h3>{note.title}</h3><p>{note.body}</p><small>{dateLabel(note.createdAt, ctx.locale, ctx.data.profile.timezone)}</small></article>)}{!ctx.data.notes.length && <p className="empty-inline">{ctx.t("مساحة لأفكارك المالية. اكتب أول ملاحظة.", "A space for your money thoughts. Add your first note.")}</p>}</div></Panel></>;
}

function Settings({ ctx }: { ctx: Ctx }) {
  const { setTheme, theme } = usePreferences(); const router = useRouter(); const [name, setName] = useState(ctx.data.profile.name); const [timezone, setTimezone] = useState(ctx.data.profile.timezone); const [preferredCurrency, setPreferredCurrency] = useState(ctx.data.profile.currency); const [confirmation, setConfirmation] = useState(""); const [deleteError, setDeleteError] = useState("");
  async function save(e: React.FormEvent) { e.preventDefault(); await ctx.mutate({ action: "profile.update", name, locale: ctx.locale, currency: preferredCurrency, timezone }).catch(() => {}); }
  async function remove() { setDeleteError(""); try { const r = await fetch("/api/finance", { method: "DELETE", headers: { "Content-Type": "application/json", "x-mizan-locale": ctx.locale }, body: JSON.stringify({ confirmation }) }); const body = await r.json(); if (!r.ok) throw new Error(body.error); router.replace("/"); router.refresh(); } catch (err) { setDeleteError(err instanceof Error ? err.message : String(err)); } }
  return <div className="settings-layout"><Panel title={ctx.t("الملف الشخصي", "Profile")} subtitle={ctx.t("تفاصيلك وتفضيلاتك الأساسية", "Your details and everyday preferences")}><form className="settings-form" onSubmit={save}><div className="settings-profile"><span className="avatar large">{ctx.data.profile.name.slice(0, 1)}</span><div><strong>{ctx.data.profile.name}</strong><p>{ctx.data.demo ? ctx.t("حساب تجريبي معزول", "Isolated demo account") : ctx.data.profile.email}</p></div></div><div className="dialog-fields"><label className="form-field"><span>{ctx.t("الاسم", "Name")}</span><input name="name" value={name} onChange={(e) => setName(e.target.value)} required maxLength={100} /></label><label className="form-field"><span>{ctx.t("العملة الافتراضية", "Default currency")}</span><select value={preferredCurrency} onChange={(e) => setPreferredCurrency(e.target.value as Currency)}>{currencyOptions.map((o) => <option key={o.value}>{o.value}</option>)}</select></label><label className="form-field"><span>{ctx.t("المنطقة الزمنية", "Time zone")}</span><select value={timezone} onChange={(e) => setTimezone(e.target.value)}>{["Asia/Jerusalem", "Asia/Amman", "Asia/Riyadh", "Asia/Dubai", "Europe/London", "Europe/Berlin", "America/New_York", "UTC"].map((z) => <option key={z}>{z}</option>)}</select></label><LanguageSelect /></div><button className="btn btn-primary" disabled={ctx.busy} type="submit">{ctx.t("حفظ التفضيلات", "Save preferences")}</button></form></Panel><Panel title={ctx.t("المظهر", "Appearance")} subtitle={ctx.t("مساحة مريحة لعينك", "Make yourself comfortable")}><div className="theme-cards"><button className={theme === "light" ? "selected" : ""} onClick={() => setTheme("light")}><Sun size={25} /><strong>{ctx.t("فاتح", "Light")}</strong><span>{ctx.t("هدوء ووضوح", "Light and clear")}</span>{theme === "light" && <CheckCircle2 size={17} />}</button><button className={theme === "dark" ? "selected dark-preview" : "dark-preview"} onClick={() => setTheme("dark")}><Moon size={25} /><strong>{ctx.t("داكن", "Dark")}</strong><span>{ctx.t("توازن في المساء", "A calmer evening")}</span>{theme === "dark" && <CheckCircle2 size={17} />}</button></div></Panel><Panel title={ctx.t("بياناتك، تحت سيطرتك", "Your data, in your hands")} subtitle={ctx.t("نزّل نسخة من بياناتك في أي وقت", "Download a copy whenever you need it")}><div className="data-actions"><div><span className="category-icon"><Download size={20} /></span><div><strong>{ctx.t("نسخة كاملة من بياناتك", "Your complete data")}</strong><p>{ctx.t("الحسابات والمعاملات والأهداف والإعدادات بصيغة JSON", "Accounts, transactions, goals and preferences in JSON")}</p></div><a className="btn btn-secondary" href="/api/export?format=json">{ctx.t("تنزيل JSON", "Download JSON")}</a></div><div><span className="category-icon"><FileText size={20} /></span><div><strong>{ctx.t("سجل المعاملات", "Transaction history")}</strong><p>{ctx.t("ملف CSV قابل للفتح في تطبيقات الجداول", "A CSV file for your spreadsheet application")}</p></div><a className="btn btn-secondary" href="/api/export?format=csv">{ctx.t("تنزيل CSV", "Download CSV")}</a></div></div></Panel><Panel title={ctx.t("حذف الحساب", "Delete account")} subtitle={ctx.t("حذف دائم لحسابك وجميع بياناته المالية. لا يمكن التراجع عن ذلك.", "Permanently delete your account and all its financial data. This cannot be undone.")} className="danger-panel"><div className="delete-account-form"><label className="form-field"><span>{ctx.t("اكتب DELETE لتأكيد الحذف", "Type DELETE to confirm deletion")}</span><input dir="ltr" value={confirmation} onChange={(e) => setConfirmation(e.target.value)} autoComplete="off" placeholder="DELETE" /></label><button className="btn danger-button" disabled={confirmation !== "DELETE"} onClick={() => void remove()}><Trash2 size={16} />{ctx.t("حذف حسابي نهائيًا", "Permanently delete my account")}</button></div>{deleteError && <p className="form-error" role="alert">{deleteError}</p>}</Panel></div>;
}
